#!/usr/bin/env node
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const SUPPORTED_BACKENDS = new Set(["authad", "authldap", "authpdo"]);
const DEFAULT_GROUP = "user";

export function buildAuthBridgeSql(manifest, options = {}) {
  const normalized = normalizeManifest(manifest);
  const generatedAt = options.generatedAt ?? new Date().toISOString();
  const statements = [
    "-- Generated by scripts/sync-auth-bridge.mjs",
    `-- Backend: ${normalized.backend}`,
    "begin transaction;"
  ];

  for (const user of normalized.users) {
    statements.push(...userStatements(user, generatedAt));
  }

  statements.push("commit;");
  return `${statements.join("\n")}\n`;
}

export function normalizeManifest(manifest) {
  if (!manifest || typeof manifest !== "object" || Array.isArray(manifest)) {
    throw new Error("Auth bridge manifest must be a JSON object.");
  }

  const backend = String(manifest.backend ?? "").toLowerCase();
  if (!SUPPORTED_BACKENDS.has(backend)) {
    throw new Error("Auth bridge manifest backend must be authad, authldap, or authpdo.");
  }

  if (!Array.isArray(manifest.users)) {
    throw new Error("Auth bridge manifest must contain a users array.");
  }

  return {
    backend,
    users: manifest.users.map(normalizeUser).sort((a, b) => a.username.localeCompare(b.username))
  };
}

function normalizeUser(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Auth bridge users must be objects.");
  }

  const username = normalizeUsername(value.username);
  const displayName = stringValue(value.displayName ?? value.fullName ?? value.name) || username;
  const email = stringValue(value.email);
  const groups = normalizeGroups(value.groups);

  return {
    username,
    displayName,
    email,
    disabled: Boolean(value.disabled),
    groups
  };
}

function userStatements(user, generatedAt) {
  const userId = `user:${user.username}`;
  const statements = [
    `insert into users (
  id, username, display_name, email, password_hash, is_disabled, created_at, updated_at
) values (
  ${sql(userId)}, ${sql(user.username)}, ${sql(user.displayName)}, ${sql(user.email)}, null, ${user.disabled ? 1 : 0}, ${sql(generatedAt)}, ${sql(generatedAt)}
)
on conflict(username) do update set
  display_name = excluded.display_name,
  email = excluded.email,
  is_disabled = excluded.is_disabled,
  updated_at = excluded.updated_at;`,
    `delete from user_groups
where user_id in (select id from users where username = ${sql(user.username)});`
  ];

  for (const group of user.groups) {
    const groupId = `group:${group}`;
    statements.push(
      `insert into groups (id, name, created_at)
values (${sql(groupId)}, ${sql(group)}, ${sql(generatedAt)})
on conflict(name) do nothing;`,
      `insert into user_groups (user_id, group_id, created_at)
select u.id, g.id, ${sql(generatedAt)}
from users u
join groups g on g.name = ${sql(group)}
where u.username = ${sql(user.username)}
on conflict(user_id, group_id) do nothing;`
    );
  }

  return statements;
}

function normalizeUsername(value) {
  const username = stringValue(value)
    ?.toLowerCase()
    .replace(/[^a-z0-9_.@-]+/g, "_");
  if (!username) throw new Error("Auth bridge user is missing a username.");
  return username;
}

function normalizeGroups(value) {
  const groups = Array.isArray(value) ? value : [];
  const normalized = groups
    .map(stringValue)
    .filter(Boolean)
    .map((group) =>
      group
        .replace(/^@+/, "")
        .toLowerCase()
        .replace(/[^a-z0-9_.-]+/g, "_")
    )
    .filter(Boolean);

  return [...new Set(normalized.length > 0 ? normalized : [DEFAULT_GROUP])].sort();
}

function stringValue(value) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed || null;
}

function sql(value) {
  if (value === null || value === undefined) return "null";
  return `'${String(value).replaceAll("'", "''")}'`;
}

async function main(argv) {
  const args = parseArgs(argv);
  if (!args.input) {
    throw new Error(
      "Usage: node scripts/sync-auth-bridge.mjs --input users.json [--sql-out out.sql]"
    );
  }

  const manifest = JSON.parse(await readFile(args.input, "utf8"));
  const sqlText = buildAuthBridgeSql(manifest);

  if (args.sqlOut) {
    await mkdir(path.dirname(args.sqlOut), { recursive: true });
    await writeFile(args.sqlOut, sqlText);
  } else {
    process.stdout.write(sqlText);
  }
}

function parseArgs(argv) {
  const args = { input: null, sqlOut: null };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === "--input") args.input = argv[++index] ?? null;
    else if (arg === "--sql-out") args.sqlOut = argv[++index] ?? null;
  }

  return args;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1]);
if (isMain) {
  main(process.argv.slice(2)).catch((error) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  });
}
